from fractions import Fraction

def average_cost_fills(fills,mark_cents,initial_cash=100000):
    # Complete replay from flat. Inputs are synthetic already-confirmed fills.
    if type(fills) is not list or len(fills)>1000:
        raise ValueError("expected at most1000confirmed fills")
    if type(mark_cents) is not int or not 1<=mark_cents<=1000000:
        raise ValueError("expected bounded positive integer mark cents")
    if type(initial_cash) is not int or not 0<=initial_cash<=1000000000:
        raise ValueError("expected bounded nonnegative integer initial cash")
    position=0;average=Fraction(0);cash=Fraction(initial_cash)
    realized=Fraction(0);fees=0;seen=set()
    for row in fills:
        if type(row) is not tuple or len(row)!=4:
            raise ValueError("expected(execution_id,signed_shares,price_cents,fee_cents)")
        eid,delta,price,fee=row
        if type(eid) is not str or not eid or len(eid)>30 or eid in seen:
            raise ValueError("expected unique nonempty execution ids")
        if type(delta) is not int or not 1<=abs(delta)<=1000000:
            raise ValueError("expected bounded nonzero signed integer shares")
        if type(price) is not int or not 1<=price<=1000000 or type(fee) is not int or not 0<=fee<=1000000:
            raise ValueError("expected bounded integer price and nonnegative fee cents")
        seen.add(eid)
        next_position=position+delta
        if position==0 or position*delta>0:
            average=(abs(position)*average+abs(delta)*price)/(abs(position)+abs(delta))
        else:
            closing=min(abs(position),abs(delta))
            realized+=closing*(price-average)*(1 if position>0 else -1)
            if next_position==0:
                average=Fraction(0)
            elif position*next_position<0:
                average=Fraction(price)  # excess fill opens the reversed side
        cash-=delta*price+fee
        fees+=fee;position=next_position
    unrealized=position*(mark_cents-average)
    equity=cash+position*mark_cents
    return {"position":position,"average":average,"cash":cash,"realized_gross":realized,
            "unrealized":unrealized,"fees":fees,"equity":equity,
            "net_pnl":equity-initial_cash}

fills=[("E1",10,1000,5),("E2",10,1200,5),("E3",-5,1300,3)]
state=average_cost_fills(fills,1250)
print(*(str(state[k]) for k in ("position","average","cash","realized_gross","unrealized","fees","equity","net_pnl")))
print(state["net_pnl"]==state["realized_gross"]+state["unrealized"]-state["fees"])
reversed_state=average_cost_fills([("R1",3,1000,0),("R2",-5,1100,0)],1050)
print(*(str(reversed_state[k]) for k in ("position","average","realized_gross","unrealized","net_pnl")))

from fractions import Fraction

def reconcile_position_cash(fills,initial_cash,reported_position,reported_cash):
    if type(initial_cash) is not int or type(reported_position) is not int:
        raise ValueError("expected integer starting cash and reported position")
    if type(reported_cash) not in (int,Fraction):
        raise ValueError("expected exact reported cash")
    if type(fills) is not list or len(fills)>1000:
        raise ValueError("expected at most1000validated signed-share/price/fee tuples")
    for row in fills:
        if type(row) is not tuple or len(row)!=3 or any(type(x) is not int for x in row):
            raise ValueError("expected integer signed-share,price,fee triples")
        delta,price,fee=row
        if not 1<=abs(delta)<=1000000 or not 1<=price<=1000000 or not 0<=fee<=1000000:
            raise ValueError("fill outside bounded synthetic range")
    expected_position=sum(delta for delta,price,fee in fills)
    expected_cash=initial_cash-sum(delta*price+fee for delta,price,fee in fills)
    return reported_position-expected_position,Fraction(reported_cash)-expected_cash

fills=[(10,1000,5),(10,1200,5),(-5,1300,3)]
print(reconcile_position_cash(fills,100000,15,84487))
print(reconcile_position_cash(fills,100000,15,84490))
print(reconcile_position_cash(fills[:-1],100000,15,84487))

from collections import deque
import heapq

def net_positions(rows):
    totals = {}
    for (symbol, quantity) in rows:
        totals[symbol] = totals.get(symbol, 0) + quantity
    return [f'{symbol} {totals[symbol]}' for symbol in sorted(totals)]

print(*net_positions([('A', 5), ('A', -5), ('0Z', 3)]), sep='\n')
